// El servidor de mentira: buscar «ru» tarda 80 ms y «ruta» tarda 10 ms (a veces la red es así)
const demora = { ru: 80, ruta: 10 };
const buscar = (texto) => new Promise((r) => setTimeout(() => r('resultados para «' + texto + '»'), demora[texto]));

let pantalla = '(vacío)';            // lo que mostraría la interfaz

// Versión ingenua: el equivalente a un efecto sin limpieza
function escribirIngenuo(texto) {
  buscar(texto).then((r) => { pantalla = r; });
}
escribirIngenuo('ru');               // la persona tipea «ru»…
escribirIngenuo('ruta');             // …y enseguida «ruta»
await new Promise((r) => setTimeout(r, 120));
console.log('ingenuo  -> pantalla:', pantalla, '| lo que escribió: «ruta»');

// Versión con limpieza: cada pedido sabe si todavía vale
let vigente = 0;
function escribirCuidadoso(texto) {
  const miNumero = ++vigente;        // el efecto de limpieza de React hace lo mismo con una bandera
  buscar(texto).then((r) => { if (miNumero === vigente) pantalla = r; });
}
pantalla = '(vacío)';
escribirCuidadoso('ru');
escribirCuidadoso('ruta');
await new Promise((r) => setTimeout(r, 120));
console.log('cuidadoso -> pantalla:', pantalla);

