// Mini-caché del cliente: una entrada por clave, con datos, momento y pedido en curso.
const cache = new Map();
const FRESCO_MS = 5000;
let ahora = 0; // reloj simulado: así la salida no depende de la velocidad de la máquina

function entrada(clave) {
  if (!cache.has(clave)) cache.set(clave, { datos: undefined, desde: -Infinity, enCurso: null, oyentes: new Set() });
  return cache.get(clave);
}

function leer(clave, buscar) {
  const e = entrada(clave);
  if (ahora - e.desde < FRESCO_MS) return Promise.resolve(e.datos); // fresco: sin red
  if (!e.enCurso) {                                                  // nadie lo pidió todavía: pedir una sola vez
    e.enCurso = buscar()
      .then((d) => { e.datos = d; e.desde = ahora; e.oyentes.forEach((f) => f(d)); return d; })
      .finally(() => { e.enCurso = null; });
  }
  return e.datos !== undefined ? Promise.resolve(e.datos) : e.enCurso; // vencido con datos: devolver ya; sin datos: esperar
}

function suscribir(clave, f) { const e = entrada(clave); e.oyentes.add(f); return () => e.oyentes.delete(f); }
function invalidar(prefijo) { for (const [k, e] of cache) if (k.startsWith(prefijo)) e.desde = -Infinity; }

// --- Un servidor de mentira: guarda el estado real y cuenta cuántas veces le preguntan ---
let estadoReal = 'en ruta', llamadas = 0;
const dormir = (ms) => new Promise((r) => setTimeout(r, ms));
async function pedirPedido42() { llamadas++; const copia = estadoReal; await dormir(20); return copia; }

const log = (...a) => console.log(...a);

// 1. Tres componentes piden lo mismo a la vez
const [a, b, c] = await Promise.all([1, 2, 3].map(() => leer('pedido:42', pedirPedido42)));
log('1. tres lecturas simultáneas ->', a, b, c, '| llamadas al servidor:', llamadas);

// 2. Un segundo después: sigue fresco
ahora = 1000;
await leer('pedido:42', pedirPedido42);
log('2. a 1 s -> llamadas al servidor:', llamadas);

// 3. El pedido se entrega, pasan 6 s: la lectura devuelve lo viejo y revalida por detrás
estadoReal = 'entregado'; ahora = 6000;
const dejarDeEscuchar = suscribir('pedido:42', (d) => log('   (la pantalla se entera de:', d + ')'));
log('3. a 6 s, devuelve ya ->', await leer('pedido:42', pedirPedido42), '| llamadas:', llamadas);
await dormir(50);
dejarDeEscuchar();

// 4. Un bug: invalidar mientras hay un pedido volando
ahora = 20000;
const lenta = leer('pedido:42', pedirPedido42);        // sale con 'entregado'
estadoReal = 'devuelto';                               // el usuario lo devuelve y la app llama a invalidar
invalidar('pedido:');
await lenta; await dormir(50);
log('4. estado real: devuelto | caché cree:', cache.get('pedido:42').datos, '| ¿fresco?', ahora - cache.get('pedido:42').desde < FRESCO_MS);

import { QueryClient, QueryObserver } from '@tanstack/query-core';
const dormir = (ms) => new Promise((r) => setTimeout(r, ms));
let estadoReal = 'en ruta', llamadas = 0;
async function pedir() { llamadas++; const copia = estadoReal; await dormir(30); return copia; }

const qc = new QueryClient();
const clave = ['pedidos', 42];
const montar = (extra = {}) => new QueryObserver(qc, { queryKey: clave, queryFn: pedir, ...extra });

// 1. Dos «componentes» piden lo mismo a la vez
const a = montar(), b = montar();
const ua = a.subscribe(() => {}), ub = b.subscribe(() => {});
await dormir(100);
console.log('1. llamadas al servidor:', llamadas, '| datos:', a.getCurrentResult().data);

// 2. Tercer componente: staleTime 0 (el valor por defecto)
estadoReal = 'entregado';
const c = montar();
console.log('2. al montar: data =', c.getCurrentResult().data, '| isStale =', c.getCurrentResult().isStale);
c.subscribe(() => {});
await dormir(100);
console.log('   tras revalidar: data =', c.getCurrentResult().data, '| llamadas:', llamadas);

// 3. Cuarto componente con staleTime de 5 s
const antes = llamadas;
const d = montar({ staleTime: 5000 });
d.subscribe(() => {});
await dormir(100);
console.log('3. pedidos nuevos:', llamadas - antes, '| isStale =', d.getCurrentResult().isStale);

// 4. Invalidar con un pedido volando (el bug de mi mini-caché)
const volando = qc.refetchQueries({ queryKey: clave }); // sale con 'entregado'
estadoReal = 'devuelto';
await Promise.all([volando, qc.invalidateQueries({ queryKey: clave })]);
await dormir(100);
console.log('4. estado real: devuelto | TanStack cree:', qc.getQueryData(clave));
process.exit(0);
